function n($s){return strtr(preg_replace('/[\x{064B}-\x{0652}\x{0640}]/u','',mb_strtolower($s)),['أ'=>'ا','إ'=>'ا','آ'=>'ا','ة'=>'ه','ى'=>'ي']);}

