/* الصور: صورة مرفوعة من اللوحة > صورة في assets/img > صورة بديلة أنيقة */
function slot($n){foreach(['webp','jpg','jpeg','png'] as $x)if(is_file(R."/assets/img/$n.$x"))return "assets/img/$n.$x";return null;}
function im($r,$slot,$kind){global $base;$i=$r['img']??'';
if($i&&strpos($i,'ph/')!==0&&is_file(R.'/'.$i))return $base.'/'.e($i);
if($s=slot($slot))return $base.'/'.$s;return $base.'/ph/'.$kind.'.svg';}
function kd($s){return isset(ICONS[$s])?$s:'renovation';}
function bg($slot){global $base;return ($s=slot($slot))?$base.'/'.$s:'';}

